// The one realtime composable: it owns the SSE connection to /api/events and
// its reconnect, and stores subscribe to it — no component ever opens a socket
// itself (frontend-vue rule). The connection is a module singleton so every
// store shares one EventSource.
//
// Native EventSource rather than VueUse useEventSource on purpose: useEventSource
// exposes only "latest value" refs (event/data are shallowRefs), so watching the
// event name drops two consecutive same-named events (two stock_changed in a row
// would deliver one callback). addEventListener fires per event, which is what
// live updates need. The browser's EventSource auto-reconnects, so no retry loop
// is needed here (see DECISIONS.md).

export const REALTIME_EVENTS = ['stock_changed', 'sale_status', 'order_status'] as const
export type RealtimeEvent = (typeof REALTIME_EVENTS)[number]

type Listener = (data: unknown) => void

interface RealtimeConnection {
  source: EventSource
  listeners: Map<RealtimeEvent, Set<Listener>>
  reconnectListeners: Set<() => void>
}

export interface Realtime {
  on(event: RealtimeEvent, listener: Listener): void
  onReconnect(listener: () => void): void
}

let connection: RealtimeConnection | null = null

function parse(data: string): unknown {
  try {
    return JSON.parse(data)
  } catch {
    return null
  }
}

export function useRealtime(): Realtime {
  if (!connection) {
    const listeners = new Map<RealtimeEvent, Set<Listener>>()
    const reconnectListeners = new Set<() => void>()
    const source = new EventSource('/api/events')

    for (const name of REALTIME_EVENTS) {
      source.addEventListener(name, (event: MessageEvent) => {
        const payload = parse(event.data)
        for (const listener of listeners.get(name) ?? []) listener(payload)
      })
    }

    // The first open is the initial connection; each later open is a reconnect,
    // so refetch before resuming the stream (a missed event is never shown).
    let opened = false
    source.onopen = () => {
      if (opened) {
        for (const listener of reconnectListeners) listener()
      }
      opened = true
    }

    connection = { source, listeners, reconnectListeners }
  }
  const conn = connection
  return {
    on(event, listener) {
      const set = conn.listeners.get(event) ?? new Set<Listener>()
      set.add(listener)
      conn.listeners.set(event, set)
    },
    onReconnect(listener) {
      conn.reconnectListeners.add(listener)
    },
  }
}

import { ref } from 'vue'
import { defineStore } from 'pinia'
import { api } from '../api/client'
import type { Sale } from '../api/types'
import { useRealtime, type RealtimeEvent } from '../composables/useRealtime'

export const useSalesStore = defineStore('sales', () => {
  const sales = ref<Sale[]>([])
  // Offset between the browser clock and the backend's `server_now`, captured on
  // the last fetch. The UI counts down from `Date.now() - serverOffset`, so
  // "opens for everyone at once" depends on the backend clock, not the browser's.
  const serverOffset = ref<number | null>(null)

  // Monotonic guard: a burst of events starts several concurrent refetches, and
  // a slower, older response must not overwrite a newer one.
  let fetchSeq = 0

  async function fetchSales(): Promise<void> {
    const seq = ++fetchSeq
    const list = await api.listSales()
    if (seq !== fetchSeq) return
    sales.value = list
    serverOffset.value =
      list.length > 0 ? Date.now() - Date.parse(list[0]!.server_now) : null
  }

  async function reserve(saleId: number): Promise<void> {
    await api.reserve(saleId)
    await fetchSales()
  }

  // Applies a realtime event. Kept as its own (async) action so a test can feed
  // it events directly and assert the resulting state — the SSE wiring just
  // routes into it. The payload is not needed: stock/sale changes always
  // refetch the whole list.
  async function applyEvent(event: RealtimeEvent): Promise<void> {
    if (event !== 'stock_changed' && event !== 'sale_status') return
    try {
      await fetchSales()
    } catch {
      // A transient refetch failure is not worth surfacing; the next event or a
      // reconnect will retry.
    }
  }

  let bound = false
  function bindRealtime(): void {
    if (bound) return
    bound = true
    const rt = useRealtime()
    rt.on('stock_changed', () => void applyEvent('stock_changed'))
    rt.on('sale_status', () => void applyEvent('sale_status'))
    rt.onReconnect(() => void fetchSales())
  }

  return { sales, serverOffset, fetchSales, reserve, applyEvent, bindRealtime }
})

import { ref } from 'vue'
import { defineStore } from 'pinia'
import { api } from '../api/client'
import type { Order } from '../api/types'
import { useRealtime, type RealtimeEvent } from '../composables/useRealtime'

export const useOrdersStore = defineStore('orders', () => {
  const orders = ref<Order[]>([])

  async function fetchOrders(): Promise<void> {
    orders.value = await api.listOrders()
  }

  // The buyer's cabinet stays current via SSE. An order moves on order_status
  // (paid/cancelled), but a cancellation also rides stock_changed (hold expiry)
  // and sale_status (sale end), so refetch on any of them.
  async function applyEvent(event: RealtimeEvent): Promise<void> {
    if (
      event !== 'order_status' &&
      event !== 'stock_changed' &&
      event !== 'sale_status'
    )
      return
    try {
      await fetchOrders()
    } catch {
      // Transient refetch failure: the next event or reconnect retries.
    }
  }

  let bound = false
  function bindRealtime(): void {
    if (bound) return
    bound = true
    const rt = useRealtime()
    rt.on('order_status', () => void applyEvent('order_status'))
    rt.on('stock_changed', () => void applyEvent('stock_changed'))
    rt.on('sale_status', () => void applyEvent('sale_status'))
    rt.onReconnect(() => void fetchOrders())
  }

  return { orders, fetchOrders, applyEvent, bindRealtime }
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

// jsdom has no EventSource, so the test supplies a fake and drives it directly.
// The module-level singleton in useRealtime means each test re-imports the
// module (vi.resetModules) to get a fresh connection.
class FakeEventSource {
  static instances: FakeEventSource[] = []
  url: string
  onopen: (() => void) | null = null
  private listeners = new Map<string, ((event: MessageEvent) => void)[]>()

  constructor(url: string) {
    this.url = url
    FakeEventSource.instances.push(this)
  }

  addEventListener(type: string, handler: (event: MessageEvent) => void): void {
    const arr = this.listeners.get(type) ?? []
    arr.push(handler)
    this.listeners.set(type, arr)
  }

  emit(type: string, data: unknown): void {
    this.emitRaw(type, JSON.stringify(data))
  }

  emitRaw(type: string, raw: string): void {
    for (const handler of this.listeners.get(type) ?? []) {
      handler({ data: raw } as MessageEvent)
    }
  }

  open(): void {
    this.onopen?.()
  }
}

beforeEach(() => {
  FakeEventSource.instances = []
  vi.stubGlobal('EventSource', FakeEventSource)
  vi.resetModules()
})
afterEach(() => vi.unstubAllGlobals())

async function freshRealtime() {
  const { useRealtime } = await import('./useRealtime')
  const rt = useRealtime()
  return { rt, source: FakeEventSource.instances[0]! }
}

describe('useRealtime', () => {
  it('routes a named event to its listener with parsed data', async () => {
    const { rt, source } = await freshRealtime()
    const handler = vi.fn()
    rt.on('stock_changed', handler)

    source.emit('stock_changed', { sale_id: 1 })

    expect(handler).toHaveBeenCalledWith({ sale_id: 1 })
  })

  it('delivers two same-named events in a row', async () => {
    const { rt, source } = await freshRealtime()
    const handler = vi.fn()
    rt.on('stock_changed', handler)

    source.emit('stock_changed', { sale_id: 1 })
    source.emit('stock_changed', { sale_id: 2 })

    expect(handler).toHaveBeenCalledTimes(2)
    expect(handler).toHaveBeenNthCalledWith(2, { sale_id: 2 })
  })

  it('routes different events to their own listeners', async () => {
    const { rt, source } = await freshRealtime()
    const stock = vi.fn()
    const order = vi.fn()
    rt.on('stock_changed', stock)
    rt.on('order_status', order)

    source.emit('order_status', { order_id: 7, status: 'paid' })

    expect(order).toHaveBeenCalledWith({ order_id: 7, status: 'paid' })
    expect(stock).not.toHaveBeenCalled()
  })

  it('refetches on reconnect but not the initial open', async () => {
    const { rt, source } = await freshRealtime()
    const refetch = vi.fn()
    rt.onReconnect(refetch)

    source.open() // initial connection
    expect(refetch).not.toHaveBeenCalled()

    source.open() // reconnect
    expect(refetch).toHaveBeenCalledTimes(1)
  })

  it('passes null for non-JSON event data', async () => {
    const { rt, source } = await freshRealtime()
    const handler = vi.fn()
    rt.on('stock_changed', handler)

    source.emitRaw('stock_changed', 'not json')

    expect(handler).toHaveBeenCalledWith(null)
  })
})

