2	import { computed, onMounted, ref } from 'vue'
3	import { useTimestamp } from '@vueuse/core'
4	import { ApiError } from '../api/client'
5	import type { Sale } from '../api/types'
6	import { formatPrice } from '../lib/money'
7	import { useSalesStore } from '../stores/sales'
8	
9	const store = useSalesStore()
10	// A ticking browser clock; combined with the store's serverOffset it becomes
11	// backend time, so the countdown does not drift with the viewer's own clock.
12	const now = useTimestamp({ interval: 1000 })
13	
14	const reserveError = ref<string | null>(null)
15	
16	onMounted(async () => {
17	  store.bindRealtime()
18	  try {
19	    await store.fetchSales()
20	  } catch (e) {
21	    reserveError.value = e instanceof ApiError ? e.message : 'Could not load sales'
22	  }
23	})
24	
25	const serverNow = computed(() =>
26	  store.serverOffset === null ? null : now.value - store.serverOffset,
27	)
28	
29	type Phase = 'upcoming' | 'active' | 'ended'
30	
31	function phaseOf(sale: Sale): Phase {
32	  if (serverNow.value === null) return sale.phase
33	  const starts = Date.parse(sale.starts_at)
34	  const ends = Date.parse(sale.ends_at)
35	  if (serverNow.value < starts) return 'upcoming'
36	  if (serverNow.value < ends) return 'active'
37	  return 'ended'
38	}
39	
40	function secondsUntil(instant: string): number {
41	  if (serverNow.value === null) return 0
42	  return Math.max(0, Math.ceil((Date.parse(instant) - serverNow.value) / 1000))
43	}
44	
45	function countdown(seconds: number): string {
46	  const m = Math.floor(seconds / 60)
47	  const s = seconds % 60
48	  return `${m}:${String(s).padStart(2, '0')}`
49	}
50	
51	async function reserve(sale: Sale) {
52	  reserveError.value = null
53	  try {
54	    await store.reserve(sale.id)
55	  } catch (e) {
56	    reserveError.value = e instanceof ApiError ? e.message : 'Could not reserve'
57	  }
58	}
59	</script>
60	
61	<template>
62	  <main>
63	    <h1>Flash sales</h1>
64	    <p v-if="reserveError" role="alert">{{ reserveError }}</p>
65	
66	    <ul class="sales">
67	      <li v-for="sale in store.sales" :key="sale.id" class="sale">
68	        <div>
69	          <h2>{{ sale.title }}</h2>
70	          <p class="price">{{ formatPrice(sale.price_minor) }}</p>
71	          <p class="stock">
72	            <template v-if="phaseOf(sale) === 'upcoming'">
73	              Starts in {{ countdown(secondsUntil(sale.starts_at)) }}
74	            </template>
75	            <template v-else-if="phaseOf(sale) === 'active'">
76	              {{ sale.available }} of {{ sale.quantity }} left · ends in
77	              {{ countdown(secondsUntil(sale.ends_at)) }}
78	            </template>
79	            <template v-else>Ended</template>
80	          </p>
81	        </div>
82	        <button
83	          type="button"
84	          :disabled="phaseOf(sale) !== 'active' || sale.available === 0"
85	          @click="reserve(sale)"
86	        >
87	          <template v-if="phaseOf(sale) === 'ended'">Ended</template>
88	          <template v-else-if="sale.available === 0">Sold out</template>
89	          <template v-else>Add to cart</template>
90	        </button>
91	      </li>
92	    </ul>
93	
94	    <p v-if="store.sales.length === 0" class="empty">No sales yet.</p>
95	  </main>
96	</template>
